"""📝️ Every bilingual sentence of `reclaimed-steel-i-beam` (English first, German second): summary, references, decisions per scale, thermal and structural assumptions.

@see ./author-reclaimed-steel-i-beam.py — the entry point that reads `TEXT`
"""


def t(en, de):
    """🗣️ A bilingual text."""
    return {"en": en, "de": de}


def decisions(silhouette, retained, merged, omitted, thin, hatching, styles, overlays):
    """📋️ The eight decision texts of one representation."""
    return {"silhouette": silhouette, "retained": retained, "merged": merged, "omitted": omitted, "thinElements": thin, "hatching": hatching, "styles": styles, "overlays": overlays}


